def transform(grid):
    h,w=len(grid),len(grid[0])
    # Template silhouette is the compact 1-object above/before palette.
    pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]==1}
    comps=[]
    while pts:
        p=pts.pop(); comp={p}; todo=[p]
        while todo:
            r,c=todo.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in pts: pts.remove(q);comp.add(q);todo.append(q)
        comps.append(comp)
    shapecomp=max(comps,key=len)
    r0=min(r for r,c in shapecomp); r1=max(r for r,c in shapecomp)
    c0=min(c for r,c in shapecomp)
    shape={(r-r0,c-c0) for r,c in shapecomp}
    # Palette occupies a repeated narrow rectangle; use all its nonzero values including 1.
    # Determine the palette rows/columns by scanning full rows/columns with consistent colors.
    candidates=[]
    for r in range(h):
        vals=[grid[r][c] for c in range(w) if grid[r][c]!=0]
        if len(vals)>=3 and len(set(vals))<=3: candidates.append(('row',r,vals))
    if candidates:
        # Palette horizontal: gather colored band columns, preserving sequence.
        r=max(candidates,key=lambda x:len(x[2]))[1]
        colors=[grid[r][c] for c in range(w) if grid[r][c]!=0]
    else:
        c=max(range(w),key=lambda c:sum(grid[r][c]!=0 for r in range(h)))
        colors=[grid[r][c] for r in range(h) if grid[r][c]!=0]
    if 1 not in colors: return [row[:] for row in grid]
    out=[[0]*w for _ in range(h)]
    dh=r1-r0+1
    start=r0-colors.index(1)*dh
    for i,col in enumerate(colors):
        for dr,dc in shape:
            rr=start+i*dh+dr;cc=c0+dc
            if 0<=rr<h and 0<=cc<w:out[rr][cc]=col
    return out
